class Solution:
    def smallestString(self, s: str) -> str:
        last = {c: i for i, c in enumerate(s)}
        st, used = [], set()
        for i, c in enumerate(s):
            if c in used:
                continue
            while st and st[-1] > c and last[st[-1]] > i:
                used.discard(st.pop())
            st.append(c)
            used.add(c)
        return ''.join(st)

